package com.receiptledger.v1.recovery;

import android.graphics.Bitmap;import com.receiptledger.v1.document.ProjectiveTransform;import com.receiptledger.v1.ocr.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;

public final class OcrRecoveryEngine implements AutoCloseable {
 public static final int MAX_PASSES=3;private final MlKitOcrEngine ocr=new MlKitOcrEngine();private final ReceiptRecognitionPipeline pipeline=new ReceiptRecognitionPipeline();private final ExecutorService prep=Executors.newSingleThreadExecutor();private final AtomicLong sequence=new AtomicLong();
 public interface Callback{void onSuccess(RecoveryResult result);void onFailure(Exception error);}
 public void cancelPending(){sequence.incrementAndGet();}
 public void recognize(Bitmap input,ProjectiveTransform inputToSource,Callback callback){long id=sequence.incrementAndGet();ocr.recognize(input,inputToSource,new MlKitOcrEngine.Callback(){public void onSuccess(OcrDocument doc){if(id!=sequence.get())return;RecognitionCandidate original=pipeline.evaluate(RecognitionPass.ORIGINAL,doc);List<PassDiagnostic> ds=new ArrayList<>();ds.add(new PassDiagnostic(original));if(!pipeline.needsRecovery(original)){callback.onSuccess(new RecoveryResult(original,ds));return;}prepareRecovery(id,input,inputToSource,original,ds,callback);}public void onFailure(Exception e){if(id==sequence.get())callback.onFailure(e);}});}
 private void prepareRecovery(long id,Bitmap input,ProjectiveTransform mapper,RecognitionCandidate original,List<PassDiagnostic> ds,Callback cb){prep.execute(()->{if(id!=sequence.get())return;ReceiptImagePreprocessor.PreparedImage prepared;try{prepared=ReceiptImagePreprocessor.prepareContrast(input,mapper);}catch(OutOfMemoryError|RuntimeException e){if(id==sequence.get())cb.onSuccess(new RecoveryResult(original,ds));return;}runContrast(id,prepared,original,ds,cb);});}
 private void runContrast(long id,ReceiptImagePreprocessor.PreparedImage prepared,RecognitionCandidate best,List<PassDiagnostic> ds,Callback cb){ocr.recognize(prepared.bitmap,prepared.inputToSource,new MlKitOcrEngine.Callback(){public void onSuccess(OcrDocument doc){if(id!=sequence.get()){prepared.bitmap.recycle();return;}RecognitionCandidate c=pipeline.evaluate(RecognitionPass.CONTRAST,doc),next=pipeline.better(best,c);ds.add(new PassDiagnostic(c));if(!pipeline.needsRecovery(next)||ds.size()>=MAX_PASSES){prepared.bitmap.recycle();cb.onSuccess(new RecoveryResult(next,ds));return;}prep.execute(()->{if(id!=sequence.get()){prepared.bitmap.recycle();return;}try{ReceiptImagePreprocessor.adaptiveBinaryInPlace(prepared.bitmap);}catch(OutOfMemoryError|RuntimeException e){prepared.bitmap.recycle();cb.onSuccess(new RecoveryResult(next,ds));return;}runBinary(id,prepared,next,ds,cb);});}public void onFailure(Exception e){if(id!=sequence.get()){prepared.bitmap.recycle();return;}prep.execute(()->{try{ReceiptImagePreprocessor.adaptiveBinaryInPlace(prepared.bitmap);runBinary(id,prepared,best,ds,cb);}catch(Throwable t){prepared.bitmap.recycle();if(id==sequence.get())cb.onSuccess(new RecoveryResult(best,ds));}});}});}
 private void runBinary(long id,ReceiptImagePreprocessor.PreparedImage prepared,RecognitionCandidate best,List<PassDiagnostic> ds,Callback cb){ocr.recognize(prepared.bitmap,prepared.inputToSource,new MlKitOcrEngine.Callback(){public void onSuccess(OcrDocument doc){if(id!=sequence.get()){prepared.bitmap.recycle();return;}RecognitionCandidate c=pipeline.evaluate(RecognitionPass.BINARY,doc),next=pipeline.better(best,c);ds.add(new PassDiagnostic(c));prepared.bitmap.recycle();cb.onSuccess(new RecoveryResult(next,ds));}public void onFailure(Exception e){prepared.bitmap.recycle();if(id==sequence.get())cb.onSuccess(new RecoveryResult(best,ds));}});}
 @Override public void close(){cancelPending();prep.shutdownNow();ocr.close();}
}
